SELECT DATE_TRUNC('QUARTER', paid_at) AS quarter_start, CASE WHEN amount >= 1450 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, COUNT(*) AS cnt, MIN(paid_at) AS started_at, MAX(paid_at) AS last_seen, RANK() OVER (PARTITION BY DATE_TRUNC('QUARTER', paid_at) ORDER BY COUNT(*) DESC) AS cnt_rank FROM payments GROUP BY quarter_start, amount_tier ORDER BY amount_tier DESC NULLS FIRST
